import test from 'node:test';
import assert from 'node:assert/strict';
import {promisify} from 'node:util';
import {execFile} from 'node:child_process';
import {writeFile,readFile,stat} from 'node:fs/promises';
import {testServer} from '../../server/test/helpers.js';
const exec=promisify(execFile);
async function fixture(fn) {
  const server=await testServer();
  try {
    const request=server.agent(),recipient=server.agent();
    const signup=await request('POST','/auth/signup',{name:'CLI Owner',email:'owner@cli.test',password:'long cli password'});
    const user=(await recipient('POST','/auth/signup',{name:'CLI Recipient',email:'recipient@cli.test',password:'long cli password'})).data.user;
    const token=(await request('POST','/tokens',{name:'CLI access',scopes:['*']})).data.token;
    const config=server.ctx.config.dataDir+'/cli.json';
    await writeFile(config,JSON.stringify({url:server.url,token}),{mode:0o600});
    const cli=async(args,{file=config,json=true}={})=>{
      const result=await exec(process.execPath,[new URL('../bin/crew.js',import.meta.url).pathname,...args,'--config',file,...(json?['--json']:[])],{timeout:6000});
      return json?JSON.parse(result.stdout):result.stdout;
    };
    await fn({server,request,recipient,user,owner:signup.data.user,config,cli,token});
  }finally{await server.close();}
}
const cases={
  'people CLI help describes operational options without contacting a server':async({cli})=>{
    const help=await cli(['invite','--help'],{json:false});assert.match(help,/--link URL/);assert.match(help,/--projects/);
    const token=await cli(['token','--help'],{json:false});assert.match(token,/--save-to/);assert.match(token,/Scope grants/);
  },
  'token-authenticated CLI creates reads and renames organizations':async({cli})=>{
    const org=(await cli(['org','create','--name','CLI organization'])).organization;
    assert.equal((await cli(['org','show',org.id])).organization.role,'owner');
    await cli(['org','rename',org.id,'--name','Renamed CLI']);
    assert.equal((await cli(['org','list'])).items[0].name,'Renamed CLI');
  },
  'CLI membership commands enforce explicit removal and preserve role state':async({cli,user})=>{
    const org=(await cli(['org','create','--name','Membership CLI'])).organization;
    await cli(['org','add',org.id,'--user',user.id]);
    await cli(['org','role',org.id,'--user',user.id,'--role','guest']);
    assert.equal((await cli(['org','members',org.id])).items.find(m=>m.userId===user.id).role,'guest');
    await assert.rejects(cli(['org','remove',org.id,'--user',user.id]),/requires --yes/);
    await cli(['org','remove',org.id,'--user',user.id,'--yes']);
    assert(!(await cli(['org','members',org.id])).items.some(m=>m.userId===user.id));
  },
  'CLI team lifecycle and roster changes persist through real API':async({cli,user})=>{
    const org=(await cli(['org','create','--name','Team CLI'])).organization;await cli(['org','add',org.id,'--user',user.id]);
    const team=(await cli(['team','create','--org',org.id,'--name','Delivery','--description','First'])).team;
    await cli(['team','add',team.id,'--user',user.id]);assert.equal((await cli(['team','members',team.id])).items[0].userId,user.id);
    await cli(['team','update',team.id,'--description','']);assert.equal((await cli(['team','show',team.id])).team.description,'');
    assert.equal((await cli(['team','list','--org',org.id])).items[0].name,'Delivery');
    await cli(['team','remove',team.id,'--user',user.id,'--yes']);await assert.rejects(cli(['team','delete',team.id]),/requires --yes/);
    await cli(['team','delete',team.id,'--yes']);assert.deepEqual((await cli(['team','list','--org',org.id])).items,[]);
  },
  'CLI invitation creation preview acceptance and replay use exact recipient':async({server,cli,recipient,user})=>{
    const org=(await cli(['org','create','--name','Invite CLI'])).organization;
    const invitation=(await cli(['invite','create','--org',org.id,'--email',user.email,'--role','member','--hours','24'])).invitation;
    const rows=(await cli(['invite','outbox','--org',org.id])).items;const link=rows.find(item=>item.payload.invitationId===invitation.id).payload.link;
    assert.equal((await cli(['invite','preview','--link',link])).invitation.email,user.email);
    const token=(await recipient('POST','/tokens',{name:'Acceptance',scopes:['*']})).data.token;
    const file=server.ctx.config.dataDir+'/recipient.json';await writeFile(file,JSON.stringify({url:server.url,token}));
    assert.equal((await cli(['invite','accept','--link',link],{file})).membership.role,'member');
    await assert.rejects(cli(['invite','accept','--link',link],{file}),/accepted/);
    assert.equal((await cli(['invite','list','--org',org.id,'--state','accepted'])).items[0].id,invitation.id);
  },
  'CLI invitation revoke requires confirmation and invalidates link':async({cli,user})=>{
    const org=(await cli(['org','create','--name','Revocation CLI'])).organization;
    const invitation=(await cli(['invite','create','--org',org.id,'--email',user.email])).invitation;
    await assert.rejects(cli(['invite','revoke',invitation.id]),/requires --yes/);
    assert.equal((await cli(['invite','revoke',invitation.id,'--yes'])).invitation.state,'revoked');
  },
  'CLI token save uses restricted config and immediate revoke breaks actual CLI auth':async({server,cli})=>{
    const saved=server.ctx.config.dataDir+'/saved-token.json';
    const result=await cli(['token','create','--name','Saved token','--scopes','self:read','--days','2','--save-to',saved]);assert.equal(result.token,undefined);
    const config=JSON.parse(await readFile(saved,'utf8'));assert(config.token);assert.equal((await stat(saved)).mode&0o777,0o600);
    assert.equal((await cli(['whoami'],{file:saved})).auth.kind,'token');
    await assert.rejects(cli(['org','list'],{file:saved}),/lacks org:read/);
    await cli(['token','revoke',result.personalToken.id,'--yes']);await assert.rejects(cli(['whoami'],{file:saved}),/Please sign in/);
  },
  'CLI scoped token denial and filtered security audit preserve organization boundary':async({server,cli,user})=>{
    const org=(await cli(['org','create','--name','Audit CLI'])).organization;
    await cli(['org','add',org.id,'--user',user.id]);
    const audit=await cli(['org','audit',org.id,'--action','member_added','--entity',user.id]);assert.equal(audit.items[0].after.role,'member');
    const result=await cli(['token','create','--name','Read only','--scopes','org:read,self:read']);
    const file=server.ctx.config.dataDir+'/readonly.json';await writeFile(file,JSON.stringify({url:server.url,token:result.token}));
    assert.equal((await cli(['org','show',org.id],{file})).organization.id,org.id);
    await assert.rejects(cli(['org','rename',org.id,'--name','Denied'],{file}),/lacks org:manage/);
    assert.equal((await cli(['org','show',org.id])).organization.name,'Audit CLI');
  },
  'CLI cursor options traverse distinct organization pages':async({cli})=>{
    await cli(['org','create','--name','First']);await cli(['org','create','--name','Second']);
    const first=await cli(['org','list','--limit','1']);const next=await cli(['org','list','--limit','1','--cursor',first.nextCursor]);
    assert.notEqual(first.items[0].id,next.items[0].id);assert.equal(next.nextCursor,null);
  }
};
for(const [name,fn] of Object.entries(cases))test(name,()=>fixture(fn));

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {hashToken} from '../src/http/middleware/auth.js';
import {sanitizeAudit} from '../src/modules/people/audit.js';
async function fixture(fn) {
  const s=await testServer();
  try {
    const owner=s.agent(),member=s.agent(),other=s.agent();
    const signup=async(agent,name)=>(await agent('POST','/auth/signup',{name,email:name+'@crew.test',password:'correct horse battery'})).data.user;
    const user=await signup(owner,'owner'),memberUser=await signup(member,'member'),outsider=await signup(other,'other');
    const org=(await owner('POST','/orgs',{name:'Token Team'})).data.organization;
    await owner('POST','/orgs/'+org.id+'/members',{userId:memberUser.id,role:'member'});
    const project=(await owner('POST','/orgs/'+org.id+'/projects',{key:'API',name:'API project'})).data.project;
    const create=async(body={})=>owner('POST','/tokens',{name:'Automation',scopes:['*'],...body});
    const bearer=token=>(method,path,body)=>owner(method,path,body,{authorization:'Bearer '+token});
    await fn({s,owner,member,other,user,memberUser,outsider,org,project,create,bearer});
  }finally{await s.close();}
}
const cases={
  'personal token is returned once, stored hashed, and accepted as bearer identity':async({s,owner,create,bearer,user})=>{
    const response=await create({expiresInDays:2});assert.equal(response.status,201);
    const {token,personalToken}=response.data;assert.equal(personalToken.state,'active');assert(personalToken.expiresAt);
    const row=s.ctx.db.prepare('SELECT * FROM api_tokens WHERE id=?').get(personalToken.id);assert.equal(row.token_hash,hashToken(token));
    const me=await bearer(token)('GET','/me');assert.equal(me.data.auth.kind,'token');assert.equal(me.data.user.id,user.id);
    const list=await owner('GET','/tokens');assert.equal(list.data.items[0].name,'Automation');assert(list.data.items[0].lastUsedAt);assert(!JSON.stringify(list.data).includes(token));assert(!JSON.stringify(list.data).includes(row.token_hash));
  },
  'read scope cannot mutate, read other namespaces, or fetch credential-bearing outbox':async({create,bearer,org,project})=>{
    const token=(await create({scopes:['self:read','project:read']})).data.token;const request=bearer(token);
    assert.equal((await request('GET','/projects/'+project.id)).status,200);
    assert.equal((await request('GET','/orgs/'+org.id)).status,403);
    assert.equal((await request('PATCH','/projects/'+project.id,{name:'Denied'})).status,403);
    assert.equal((await request('GET','/me/outbox')).status,403);
  },
  'namespace and global scopes authorize only permitted account role':async({member,org,project,bearer})=>{
    const result=await member('POST','/tokens',{name:'Member tool',scopes:['*']});assert.equal(result.status,201);
    const request=bearer(result.data.token);assert.equal((await request('GET','/projects/'+project.id)).status,200);
    assert.equal((await request('PATCH','/orgs/'+org.id,{name:'Denied'})).status,403);
    const narrow=await member('POST','/tokens',{name:'Read project',scopes:['project:*']});
    assert.equal((await bearer(narrow.data.token)('GET','/projects/'+project.id+'/workflow')).status,200);
    assert.equal((await bearer(narrow.data.token)('POST','/projects/'+project.id+'/issues',{title:'Denied by namespace'})).status,403);
  },
  'guest bearer scope never bypasses a missing project grant':async({owner,member,memberUser,org,project,bearer})=>{
    await owner('PATCH','/orgs/'+org.id+'/members/'+memberUser.id,{role:'guest'});
    const token=(await member('POST','/tokens',{name:'Guest tool',scopes:['*']})).data.token;
    assert.equal((await bearer(token)('GET','/projects/'+project.id)).status,403);
    await owner('POST','/projects/'+project.id+'/guests',{userId:memberUser.id});
    assert.equal((await bearer(token)('GET','/projects/'+project.id)).status,200);
    assert.equal((await bearer(token)('POST','/projects/'+project.id+'/issues',{title:'Denied'})).status,403);
  },
  'token revocation takes effect immediately including caller revoking itself':async({create,bearer})=>{
    const {token,personalToken}=(await create()).data;const request=bearer(token);
    const revoked=await request('DELETE','/tokens/'+personalToken.id);assert.equal(revoked.data.personalToken.state,'revoked');
    assert.equal((await request('GET','/me')).status,401);
  },
  'expired and tampered bearer tokens never fall back to valid cookie':async({s,create,bearer})=>{
    const {token,personalToken}=(await create()).data;
    assert.equal((await bearer(token+'x')('GET','/me')).status,401);
    s.ctx.db.prepare('UPDATE api_tokens SET expires_at=? WHERE id=?').run('2000-01-01T00:00:00Z',personalToken.id);
    assert.equal((await bearer(token)('GET','/me')).status,401);
  },
  'token cannot mint broader exact namespace or wildcard scopes':async({create,bearer})=>{
    const token=(await create({scopes:['self:read','self:write']})).data.token;const request=bearer(token);
    assert.equal((await request('POST','/tokens',{name:'Escalation',scopes:['*']})).status,403);
    assert.equal((await request('POST','/tokens',{name:'Escalation',scopes:['project:*']})).status,403);
    assert.equal((await request('POST','/tokens',{name:'Subset',scopes:['self:read']})).status,201);
  },
  'tokens are personal and validation returns actionable field details':async({owner,member,create})=>{
    const {personalToken}=(await create()).data;assert.equal((await member('DELETE','/tokens/'+personalToken.id)).status,404);
    const invalid=await owner('POST','/tokens',{name:'bad',scopes:['admin:everything']});assert.equal(invalid.status,422);assert(invalid.data.error.details.scopes);
    assert.equal((await owner('POST','/tokens',{name:'bad',expiresInDays:0})).status,422);
    assert.equal((await owner('GET','/tokens?state=unknown')).status,422);
  },
  'password change and reset revoke existing personal API tokens':async({owner,user,create,bearer})=>{
    const first=(await create()).data.token;
    await owner('POST','/auth/password/change',{currentPassword:'correct horse battery',password:'changed long password'});
    assert.equal((await bearer(first)('GET','/me')).status,401);
    const second=(await create()).data.token;await owner('POST','/auth/password/reset/request',{email:user.email});
    const reset=(await owner('GET','/me/outbox?kind=reset')).data.items[0];
    const token=decodeURIComponent(reset.payload.link.split('token=')[1]);
    await owner('POST','/auth/password/reset',{token,password:'another long password'});
    assert.equal((await bearer(second)('GET','/me')).status,401);
  },
  'token list pages preserve metadata and filter state before cursor pagination':async({owner,create})=>{
    const a=(await create({name:'first'})).data.personalToken;await create({name:'second'});
    const first=await owner('GET','/tokens?limit=1');assert.equal(first.data.items.length,1);assert(first.data.nextCursor);
    const next=await owner('GET','/tokens?limit=1&cursor='+encodeURIComponent(first.data.nextCursor));assert.equal(next.data.items.length,1);assert.notEqual(next.data.items[0].id,first.data.items[0].id);
    await owner('DELETE','/tokens/'+a.id);const revoked=await owner('GET','/tokens?state=revoked');assert.deepEqual(revoked.data.items.map(t=>t.id),[a.id]);
  },
  'security audit persists organization changes with actor and before-after summaries':async({owner,user,org})=>{
    await owner('PATCH','/orgs/'+org.id,{name:'Renamed organization'});
    const audit=await owner('GET','/orgs/'+org.id+'/audit?action=updated&entityType=organization');
    assert.equal(audit.status,200);const event=audit.data.items[0];assert.equal(event.actorId,user.id);assert.equal(event.before.name,'Token Team');assert.equal(event.after.name,'Renamed organization');assert.equal(event.orgId,org.id);
  },
  'security audit filters actor target time type and opaque cursors':async({owner,org,user,create})=>{
    await owner('PATCH','/orgs/'+org.id,{name:'Second'});await owner('PATCH','/orgs/'+org.id,{name:'Third'});
    const base='/orgs/'+org.id+'/audit?entityType=organization&entityId='+org.id+'&actorId='+user.id+'&from=2000-01-01&to=2099-01-01&limit=1';
    const first=await owner('GET',base);assert.equal(first.data.items.length,1);assert(first.data.nextCursor);
    const next=await owner('GET',base+'&cursor='+encodeURIComponent(first.data.nextCursor));assert.equal(next.data.items.length,1);assert.notEqual(next.data.items[0].id,first.data.items[0].id);
    assert.equal((await owner('GET','/orgs/'+org.id+'/audit?from=bad')).status,422);
    assert.equal((await owner('GET','/orgs/'+org.id+'/audit?from=2099-01-01&to=2000-01-01')).status,422);
  },
  'security audit denies members outsiders and insufficient scoped admin tokens':async({owner,member,other,org,create,bearer})=>{
    for(const request of [member,other])assert.equal((await request('GET','/orgs/'+org.id+'/audit')).status,403);
    const token=(await create({scopes:['org:read']})).data.token;assert.equal((await bearer(token)('GET','/orgs/'+org.id+'/audit')).status,403);
  },
  'account audit contains own security actions without private credential values':async({owner,create,bearer})=>{
    const {token}=(await create()).data;await bearer(token)('GET','/me');
    const audit=await owner('GET','/me/audit?entityType=api_token');assert.equal(audit.status,200);assert(audit.data.items.some(e=>e.after?.name==='Automation'));
    const serialized=JSON.stringify(audit.data);assert(!serialized.includes(token));assert(!serialized.includes(hashToken(token)));assert(!serialized.includes('password_hash'));
  },
  'audit sanitizer removes nested secrets and lifecycle cleanup unregisters subscriber':async({s,owner,user,org})=>{
    assert.deepEqual(sanitizeAudit({name:'Visible',password_hash:'hidden',token:'hidden',payload:{link:'hidden'},scopes:['self:read']}),{name:'Visible',scopes:['self:read']});
    s.ctx.bus.emit({actorId:user.id,orgId:org.id,entityType:'user',entityId:user.id,action:'profile_updated',after:{name:'Visible',password:'hidden',resetLink:'hidden'}});
    const audit=await owner('GET','/orgs/'+org.id+'/audit?action=profile_updated');assert.deepEqual(audit.data.items[0].after,{name:'Visible'});
    const before=s.ctx.bus.listenerCount;s.ctx.cleanup();assert(s.ctx.bus.listenerCount<before);s.ctx.cleanup();
  },
  'every currently integrated work route rejects missing token scopes and missing project access':async({owner,member,memberUser,org,project,create,bearer})=>{
    const issue=(await owner('POST','/projects/'+project.id+'/issues',{title:'Protected issue'})).data.issue;
    const token=(await create({scopes:['self:read']})).data.token;
    for(const path of ['/projects','/orgs/'+org.id+'/projects','/orgs/'+org.id+'/issues','/projects/'+project.id,'/projects/'+project.id+'/workflow','/projects/'+project.id+'/board','/projects/'+project.id+'/issues','/projects/'+project.id+'/labels','/issues/'+issue.id,'/issues/'+issue.id+'/comments','/issues/'+issue.id+'/relations'])assert.equal((await bearer(token)('GET',path)).status,403,path);
    await owner('PATCH','/orgs/'+org.id+'/members/'+memberUser.id,{role:'guest'});
    for(const path of ['/projects/'+project.id+'/board','/issues/'+issue.id+'/comments','/issues/'+issue.id+'/relations'])assert.equal((await member('GET',path)).status,403,path);
    assert.deepEqual((await member('GET','/orgs/'+org.id+'/issues?limit=1')).data.items,[]);
  }
};
for(const [name,fn] of Object.entries(cases))test(name,()=>fixture(fn));
